parameters.jsonBody:
={{
  JSON.stringify({
    channel: "YOUR_SLACK_CHANNEL_ID",
    text: "🚨 VIP ESCALATION: " + $json.order_number + " ($" + $json.order_value + ") - " + $json.customer_name,
    blocks: [
      {
        type: "header",
        text: {
          type: "plain_text",
          text: "🚨 VIP FINANCIAL ESCALATION: " + $json.order_number,
          emoji: true
        }
      },
      {
        type: "section",
        fields: [
          {
            type: "mrkdwn",
            text: "*Customer:*\n" + $json.customer_name + " (<mailto:" + $json.customer_email + "|" + $json.customer_email + ">)"
          },
          {
            type: "mrkdwn",
            text: "*LTV Tier:*\n⭐ " + $json.ltv_tier.toUpperCase() + " ($" + $json.total_spend.toLocaleString() + " across " + $json.order_count + " orders)"
          },
          {
            type: "mrkdwn",
            text: "*Claim Amount:*\n💰 $" + $json.order_value.toFixed(2) + " USD"
          },
          {
            type: "mrkdwn",
            text: "*Sentiment & Urgency:*\n⚠️ " + $json.sentiment.toUpperCase() + " / " + $json.urgency.toUpperCase()
          }
        ]
      },
      {
        type: "section",
        text: {
          type: "mrkdwn",
          text: "*Trigger Reason:*\n`" + $json.escalation_reason + "`"
        }
      },
      {
        type: "section",
        text: {
          type: "mrkdwn",
          text: "*Customer Stated:*\n> \"" + ($json.raw_message || "").replace(/"/g, '\\"') + "\""
        }
      },
      {
        type: "divider"
      },
      {
        type: "section",
        text: {
          type: "mrkdwn",
          text: "*Executive Action Required:* Select an approved resolution below to execute immediately:"
        }
      },
      {
        type: "actions",
        block_id: "lumina_resolution_actions",
        elements: [
          {
            type: "button",
            text: {
              type: "plain_text",
              text: "💳 Approve $" + $json.order_value.toFixed(2) + " Refund",
              emoji: true
            },
            style: "danger",
            action_id: "lumina_refund_full",
            value: "lumina_refund_full|" + $json.ticket_id + "|" + $json.order_number + "|" + $json.order_value.toFixed(2)
          },
          {
            type: "button",
            text: {
              type: "plain_text",
              text: "🎁 Offer $" + $json.store_credit_amount + " Store Credit (+20%)",
              emoji: true
            },
            style: "primary",
            action_id: "lumina_credit_120",
            value: "lumina_credit_120|" + $json.ticket_id + "|" + $json.order_number + "|" + $json.store_credit_amount
          }
        ]
      }
    ]
  })
}}
